"use client"

import * as React from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { cva } from "class-variance-authority"
import { Button, buttonVariants } from "@/components/ui/button"
import {
  Pagination,
  PaginationContent,
  PaginationItem,
  PaginationLink,
} from "@/components/ui/pagination"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"

const barPaginationVariants = cva(
  "flex items-center rounded-md border border-edge bg-muted/60",
  {
    variants: { size: { sm: "text-xs", default: "text-sm", lg: "text-sm" } },
    defaultVariants: { size: "default" },
  },
)
const DEFAULT_LABELS = {
  navigation: "分页",
  previous: "上一页",
  next: "下一页",
  perPage: "每页",
  jump: "跳至",
  pageUnit: "页",
  jumpInput: "跳转页码",
  page: (page: number) => `第 ${page} 页`,
}
type BarPaginationProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  /** 当前页，从 1 开始 */
  page?: number
  /** 初始页 @default 1 */
  defaultPage?: number
  /** 总页数，至少按 1 页展示 */
  pageCount: number
  /** 翻页回调 */
  onPageChange?: (page: number) => void
  /** 总条数；传入时显示范围 */
  total?: number
  /** 每页条数 @default 10 */
  pageSize?: number
  /** 可选每页条数 */
  pageSizes?: readonly number[]
  /** 每页条数变化，调用方同步更新 pageCount */
  onPageSizeChange?: (size: number) => void
  /** 显示范围 @default true */
  showRange?: boolean
  /** 显示跳页输入 @default false */
  jumper?: boolean
  /** 当前页两侧页数 @default 1 */
  siblings?: number
  /** 生成真实链接；未传入时使用按钮 */
  getHref?: (page: number) => string
  /** 高度档 @default "default" */
  size?: "sm" | "default" | "lg"
  /** 覆盖默认文案 */
  labels?: Partial<typeof DEFAULT_LABELS>
}

function BarPagination({
  page: pageProp,
  defaultPage = 1,
  pageCount,
  onPageChange,
  total,
  pageSize = 10,
  pageSizes,
  onPageSizeChange,
  showRange = true,
  jumper = false,
  siblings = 1,
  getHref,
  size = "default",
  labels: labelsProp,
  className,
  ...props
}: BarPaginationProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const count = Math.max(1, Math.trunc(pageCount) || 1)
  const clamp = (n: number) => Math.min(count, Math.max(1, Math.trunc(n) || 1))
  const id = React.useId()
  const [rawPage, setPage] = useControllableState({
    prop: pageProp,
    defaultProp: defaultPage,
    onChange: onPageChange,
  })
  const page = clamp(rawPage)
  const [jump, setJump] = React.useState("")
  const buttonSize =
    size === "sm" ? "icon-sm" : size === "lg" ? "icon-lg" : "icon"
  const cell =
    "rounded-none border-0 font-mono tabular-nums focus-visible:ring-inset"
  // 固定槽位：总页数多于 2×siblings+5 时，始终渲染同样数量的格子（首页、末页、当前页及两侧、
  // 两个省略号或补位页码），翻页时分页条宽度不变，按钮不会在鼠标下移位
  const radius = Math.max(0, Math.trunc(siblings) || 0)
  const slots = radius * 2 + 5
  const range = (from: number, to: number) =>
    Array.from({ length: to - from + 1 }, (_, i) => from + i)
  const pages: (number | string)[] =
    count <= slots
      ? range(1, count)
      : page <= radius + 3
        ? [...range(1, slots - 2), "gap-end", count]
        : page >= count - radius - 2
          ? [1, "gap-start", ...range(count - slots + 3, count)]
          : [
              1,
              "gap-start",
              ...range(page - radius, page + radius),
              "gap-end",
              count,
            ]
  const item = (
    n: number,
    content: React.ReactNode,
    label: string,
    disabled = false,
    current = false,
  ) =>
    getHref && !disabled ? (
      <PaginationLink
        href={getHref(n)}
        size={buttonSize}
        isActive={current}
        aria-label={label}
        className={cn(
          cell,
          current &&
            "bg-foreground text-background hover:bg-foreground hover:text-background",
        )}
        onClick={(event) => {
          if (
            !event.metaKey &&
            !event.ctrlKey &&
            !event.shiftKey &&
            !event.altKey
          )
            setPage(n)
        }}
      >
        {content}
      </PaginationLink>
    ) : (
      <Button
        type="button"
        size={buttonSize}
        variant="ghost"
        aria-label={label}
        aria-current={current ? "page" : undefined}
        disabled={disabled}
        className={cn(
          cell,
          current &&
            "bg-foreground text-background hover:bg-foreground hover:text-background",
        )}
        onClick={() => setPage(n)}
      >
        {content}
      </Button>
    )
  return (
    <div
      {...props}
      data-slot="bar-pagination"
      className={cn("@container/bar-pagination w-full", className)}
    >
      <div className="flex flex-wrap items-center justify-between gap-3">
        {total !== undefined && showRange && (
          <p
            data-slot="bar-pagination-range"
            className="font-mono text-xs whitespace-nowrap text-muted-foreground tabular-nums"
          >
            {String(
              total > 0
                ? Math.min(total, (page - 1) * Math.max(1, pageSize) + 1)
                : 0,
            ).padStart(2, "0")}
            –
            {String(
              Math.min(Math.max(0, total), page * Math.max(1, pageSize)),
            ).padStart(2, "0")}{" "}
            / {total}
          </p>
        )}
        <Pagination
          aria-label={labels.navigation}
          className="mx-0 w-auto max-w-full"
        >
          <PaginationContent
            className={cn(
              barPaginationVariants({ size }),
              "gap-0 overflow-hidden [&>li+li]:border-l [&>li+li]:border-edge",
            )}
          >
            {pageSizes && (
              <PaginationItem className="hidden self-stretch @min-[30rem]/bar-pagination:flex">
                {/* 每页条数：官方 Select，触发器做成方条里的一格（无边框、透明底）。
                    触发器定宽，弹出层与它同宽、左缘对齐，选项数字与触发器数字同一列，勾与箭头同一列 */}
                <div className="flex items-center ps-2 whitespace-nowrap text-muted-foreground">
                  <span id={`${id}-per-page`}>{labels.perPage}</span>
                  <Select
                    value={pageSize}
                    onValueChange={(value) => onPageSizeChange?.(Number(value))}
                  >
                    <SelectTrigger
                      aria-labelledby={`${id}-per-page`}
                      className="h-full! w-16 justify-between gap-1 rounded-none border-0 bg-transparent! py-0 ps-2.5 pe-2 font-mono text-foreground shadow-none hover:bg-background/60! focus-visible:ring-inset [&_svg]:size-3.5!"
                    >
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent
                      alignItemWithTrigger={false}
                      align="start"
                      className="w-(--anchor-width) min-w-0"
                    >
                      {pageSizes
                        .filter((n) => n > 0)
                        .map((n) => (
                          <SelectItem
                            key={n}
                            value={n}
                            className="py-1 ps-1.5 pe-6 font-mono text-xs [&_svg]:size-3.5 [&>span:last-child]:right-1"
                          >
                            {n}
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>
              </PaginationItem>
            )}
            <PaginationItem>
              {item(
                clamp(page - 1),
                <ChevronLeft aria-hidden="true" />,
                labels.previous,
                page === 1,
              )}
            </PaginationItem>
            {pages.map((n) => (
              <PaginationItem
                key={n}
                className="hidden self-stretch @min-[30rem]/bar-pagination:flex"
              >
                {typeof n === "number" ? (
                  item(n, n, labels.page(n), false, n === page)
                ) : (
                  <span
                    aria-hidden="true"
                    className={cn(
                      buttonVariants({ variant: "ghost", size: buttonSize }),
                      cell,
                      "pointer-events-none text-muted-foreground",
                    )}
                  >
                    …
                  </span>
                )}
              </PaginationItem>
            ))}
            <PaginationItem className="px-4 font-mono tabular-nums @min-[30rem]/bar-pagination:hidden">
              <span aria-live="polite">
                {page} / {count}
              </span>
            </PaginationItem>
            <PaginationItem>
              {item(
                clamp(page + 1),
                <ChevronRight aria-hidden="true" />,
                labels.next,
                page === count,
              )}
            </PaginationItem>
            {jumper && (
              <PaginationItem className="hidden self-stretch @min-[30rem]/bar-pagination:flex">
                <label className="flex items-center gap-1 px-2 whitespace-nowrap text-muted-foreground">
                  {labels.jump}
                  <input
                    aria-label={labels.jumpInput}
                    inputMode="numeric"
                    value={jump}
                    onChange={(event) => setJump(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault()
                        if (jump.trim() && Number.isFinite(Number(jump))) {
                          const next = clamp(Number(jump))
                          setPage(next)
                          setJump("")
                          if (getHref) window.location.assign(getHref(next))
                        }
                      }
                    }}
                    className="h-[calc(100%-0.5rem)] w-10 rounded-sm border border-edge bg-background text-center font-mono text-base text-foreground outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 md:text-sm"
                  />
                  {labels.pageUnit}
                </label>
              </PaginationItem>
            )}
          </PaginationContent>
        </Pagination>
      </div>
    </div>
  )
}
export { BarPagination, barPaginationVariants }
export type { BarPaginationProps }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }
